#!/usr/bin/env node
/**
 * Generates the static legal pages from the single content source:
 *
 *   src/content/legal/terms.js   → public/terms-of-service.html
 *   src/content/legal/privacy.js → public/privacy-policy.html
 *
 * Runs as `prebuild` (see package.json) so every deploy regenerates them, and
 * the generated files are committed so the repo always shows what is live.
 *
 * Why static copies exist at all: public/privacy-policy.html is the URL
 * registered with Google for OAuth verification, and older links (sign-in
 * pages, the extension) point at both files. They used to be hand-edited and
 * drifted months away from the React /terms and /privacy routes. Now they are
 * outputs, never inputs — edit the content modules instead.
 */
import { writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { terms } from '../src/content/legal/terms.js';
import { privacy } from '../src/content/legal/privacy.js';

const here = dirname(fileURLToPath(import.meta.url));
const publicDir = resolve(here, '../public');

const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// [label](href) → <a>. Internal paths become absolute www.rivvra.com URLs so
// the static file works from anywhere it is linked.
function inline(text) {
  return esc(text).replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_, label, href) => {
    const url = href.startsWith('/') ? `https://www.rivvra.com${href}` : href;
    const ext = url.startsWith('http') ? ' target="_blank" rel="noopener noreferrer"' : '';
    return `<a href="${url}"${ext}>${label}</a>`;
  });
}

function block(b) {
  if (b.p) return `    <p>${inline(b.p)}</p>`;
  if (b.ul) return `    <ul>\n${b.ul.map((i) => `      <li>${inline(i)}</li>`).join('\n')}\n    </ul>`;
  if (b.callout) return `    <div class="callout"><p>${inline(b.callout)}</p></div>`;
  if (b.table) {
    const { head, rows } = b.table;
    return `    <div class="table-wrap"><table>\n      <thead><tr>${head.map((h) => `<th>${esc(h)}</th>`).join('')}</tr></thead>\n      <tbody>\n${rows.map((r) => `        <tr>${r.map((c) => `<td>${esc(c)}</td>`).join('')}</tr>`).join('\n')}\n      </tbody>\n    </table></div>`;
  }
  return '';
}

function page(doc) {
  const sections = doc.sections.map((s) => `  <div class="section">\n    <h2>${esc(s.heading)}</h2>\n${s.blocks.map(block).join('\n')}\n  </div>`).join('\n\n');
  return `<!DOCTYPE html>
<!-- GENERATED by scripts/build-legal-static.mjs from src/content/legal/${doc.slug}.js — do not edit by hand. -->
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${esc(doc.title)} – Rivvra</title>
  <meta name="description" content="${esc(doc.intro || doc.title)}" />
  <link rel="canonical" href="https://www.rivvra.com/${doc.slug}" />
  <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
  <link href="https://fonts.googleapis.com/css2?family=DM+Serif+Display&family=DM+Sans:wght@300;400;500&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root { --green: #2ecc8e; --green-dark: #1a9e68; --bg: #f7f9f8; --text: #1a1f1c; --muted: #5a6660; --border: #dce8e2; }
    body { font-family: 'DM Sans', sans-serif; background: var(--bg); color: var(--text); line-height: 1.75; font-size: 16px; }
    header { background: #fff; border-bottom: 1px solid var(--border); padding: 20px 40px; display: flex; align-items: center; gap: 12px; }
    header a { display: flex; align-items: center; gap: 12px; text-decoration: none; }
    .logo-text { font-family: 'DM Serif Display', serif; font-size: 22px; color: var(--text); letter-spacing: -0.3px; }
    .hero { background: linear-gradient(135deg, #1a2e25 0%, #0f1a14 100%); color: #fff; padding: 72px 40px 56px; position: relative; overflow: hidden; }
    .hero::before { content: ''; position: absolute; top: -60px; right: -60px; width: 320px; height: 320px; background: radial-gradient(circle, rgba(46,204,142,0.15) 0%, transparent 70%); border-radius: 50%; }
    .hero-inner { max-width: 760px; margin: 0 auto; position: relative; }
    .hero-tag { display: inline-block; background: rgba(46,204,142,0.15); color: var(--green); border: 1px solid rgba(46,204,142,0.3); padding: 4px 14px; border-radius: 20px; font-size: 12px; font-weight: 500; letter-spacing: 0.8px; text-transform: uppercase; margin-bottom: 20px; }
    .hero h1 { font-family: 'DM Serif Display', serif; font-size: clamp(36px, 5vw, 52px); font-weight: 400; line-height: 1.15; margin-bottom: 16px; }
    .hero p { color: rgba(255,255,255,0.6); font-size: 15px; }
    .hero .intro { color: rgba(255,255,255,0.8); font-size: 17px; margin-top: 18px; max-width: 640px; }
    main { max-width: 760px; margin: 56px auto; padding: 0 40px 80px; }
    .section { margin-bottom: 44px; padding-bottom: 44px; border-bottom: 1px solid var(--border); }
    .section:last-child { border-bottom: none; }
    h2 { font-family: 'DM Serif Display', serif; font-size: 24px; font-weight: 400; color: var(--text); margin-bottom: 16px; display: flex; align-items: center; gap: 10px; }
    h2::before { content: ''; display: inline-block; width: 4px; height: 22px; background: var(--green); border-radius: 2px; flex: none; }
    p { color: var(--muted); margin-bottom: 14px; }
    p:last-child { margin-bottom: 0; }
    ul { list-style: none; margin: 14px 0; padding: 0; }
    ul li { color: var(--muted); padding: 6px 0 6px 22px; position: relative; }
    ul li::before { content: '→'; position: absolute; left: 0; color: var(--green); font-size: 13px; }
    .callout { background: #fff; border: 1px solid var(--border); border-left: 4px solid var(--green); border-radius: 8px; padding: 20px 24px; margin: 24px 0; }
    .callout p { color: var(--text); font-size: 14px; }
    .table-wrap { overflow-x: auto; margin: 18px 0; border: 1px solid var(--border); border-radius: 8px; background: #fff; }
    table { width: 100%; border-collapse: collapse; font-size: 14px; }
    th, td { text-align: left; padding: 10px 14px; vertical-align: top; }
    th { color: var(--muted); font-weight: 500; background: #f2f6f4; }
    td { border-top: 1px solid var(--border); color: var(--muted); }
    td:first-child { color: var(--text); font-weight: 500; white-space: nowrap; }
    a { color: var(--green-dark); text-decoration: none; }
    a:hover { text-decoration: underline; }
    footer { background: #1a2e25; color: rgba(255,255,255,0.5); text-align: center; padding: 32px 40px; font-size: 13px; }
    footer a { color: var(--green); }
    @media (max-width: 600px) { header { padding: 16px 20px; } .hero { padding: 48px 20px 40px; } main { padding: 0 20px 60px; margin-top: 40px; } }
  </style>
</head>
<body>

<header>
  <a href="https://www.rivvra.com/">
    <svg width="36" height="36" viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
      <defs><linearGradient id="rg" x1="0" y1="64" x2="64" y2="0"><stop offset="0%" stop-color="#059669"/><stop offset="50%" stop-color="#10b981"/><stop offset="100%" stop-color="#34d399"/></linearGradient></defs>
      <path d="M 46 8 C 60 14 64 40 44 54 C 28 64 8 54 8 36 C 8 20 22 12 34 18 C 44 24 44 38 34 42 C 26 44 22 36 26 30" stroke="url(#rg)" stroke-width="6" fill="none" stroke-linecap="round"/>
      <circle cx="48" cy="5" r="2.5" fill="#34d399"/>
    </svg>
    <span class="logo-text">Rivvra</span>
  </a>
</header>

<div class="hero">
  <div class="hero-inner">
    <div class="hero-tag">Legal</div>
    <h1>${esc(doc.title)}</h1>
    <p>Effective Date: ${esc(doc.effectiveDate)} &nbsp;·&nbsp; Last Updated: ${esc(doc.lastUpdated)}</p>
${doc.intro ? `    <p class="intro">${esc(doc.intro)}</p>\n` : ''}  </div>
</div>

<main>

${sections}

</main>

<footer>
  <p>&copy; ${new Date().getFullYear()} Rivvra · Huemot Technology Private Limited · <a href="/terms-of-service.html">Terms of Service</a> · <a href="/privacy-policy.html">Privacy Policy</a></p>
</footer>

</body>
</html>
`;
}

const out = [
  ['terms-of-service.html', terms],
  ['privacy-policy.html', privacy],
];
for (const [file, doc] of out) {
  writeFileSync(resolve(publicDir, file), page(doc));
  console.log(`legal: wrote public/${file} (${doc.lastUpdated})`);
}
